SQL:
SELECT type 
FROM cards 
WHERE name = 'Benalish Knight';

SELECT DISTINCT code
FROM sets
WHERE type = 'expansion';

SELECT T1.CommentCount
FROM posts T1
WHERE T1.Score = (SELECT MAX(Score) FROM posts);

SELECT CAST(SUM(IIF(Consumption > 528.3, 1, 0)) AS FLOAT) * 100 / COUNT(CustomerID)
FROM yearmonth
WHERE Date = '201202';

SELECT COUNT(id)
FROM Player
WHERE birthday > '1990' AND player_name LIKE 'Aaron%';

SELECT SUM(CASE WHEN t1.id = 6 THEN t1.jumping ELSE 0 END) -
       SUM(CASE WHEN t1.id = 23 THEN t1.jumping ELSE 0 END)
FROM Player_Attributes AS t1;

SELECT code
FROM drivers
WHERE Nationality = 'American';

SELECT DISTINCT location, lat, lng
FROM circuits
WHERE country = 'Austria';

SELECT COUNT(income_id)
FROM income
WHERE amount = 50;
